priority(skill) {
	const info = get.info(skill);
	if (!info) {
		return 0;
	}
	if ("_priority" in info) {
		return info._priority;
	}
	let priority = 0;
	if (info.priority) {
		priority = info.priority * 100;
	}
	if (info.silent) {
		priority++;
	}
	if (info.equipSkill) {
		priority -= 25;
	}
	if (info.cardSkill) {
		priority -= 50;
	}
	if (info.ruleSkill) {
		priority -= 75;
	}
	info._priority = priority;
	return priority;
}

